1 public void Save ()
2 {
3 string filename = Application . persistentDataPath + " / playInfo . dat " ;
4 BinaryFormatter bf = new BinaryFormatter () ;
5 FileStream file = File . Open ( filename , FileMode . OpenOrCreate ) ;
6
7 PlayerData pd = new PlayerData () ;
8 pd . health = health ;
9
10 bf . Serialize ( file , pd ) ;
11 file . Close () ;
12 }
1 public void Load ()
2 {
3 string filename = Application . persistentDataPath + " / playInfo . dat " ;
4 if ( File . Exists ( filename ) )
5 {
6 BinaryFormatter bf = new BinaryFormatter () ;
7 FileStream file = File . Open ( filename , FileMode . Open ) ;
8 PlayerData pd = ( PlayerData ) bf . Deserialize ( file ) ;
9 file . Close () ;
10
11 health = pd . health ;
12 }
13 }
